 if(contextUnit)selectBook(contextUnit.bookId);
 document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(['book','unit','units'].includes(page)?'library':page==='quiz'||page==='report'?'':page)));
