function allStudyWords(){return DB.words.map(w=>word(w.id)).filter(w=>(allStudyType==='all'||(w.type||'word')===allStudyType)&&(allStudyScope==='all'||(allStudyDirection==='mixed'?['en','zh'].some(dir=>!rec(w.id).practice[dir]):!rec(w.id).practice[allStudyDirection])))}
const allStudyKey=()=>['all-library',allStudyDirection,allStudyType,allStudyScope].join('-');
function startAllStudy(){
 const key=allStudyKey(),existing=state.sessions[key];if(existing&&!existing.done){location.hash='quiz/'+key;return}
 const pool=allStudyWords();if(!pool.length){notify('当前范围已通过，可以切换到全部词条再练');return}
 const selected=E.shuffle(pool).slice(0,allStudyLimit),session=E.createSession(selected.map(w=>w.id),'practice',allStudyDirection,'全部词书',state.records);
 if(allStudyScope==='unfinished')session.queue=session.queue.filter(t=>!rec(t.id).practice[t.dir]);session.allBooks=true;session.totalTasks=session.queue.length;state.sessions[key]=session;save(true);location.hash='quiz/'+key;
}
function renderAllStudy(){
 const pool=allStudyWords(),selectedResume=state.sessions[allStudyKey()]&&!state.sessions[allStudyKey()].done,resumes=Object.entries(state.sessions).filter(([k,s])=>s.allBooks&&!s.done);
 $('#main').innerHTML=pageTop('<a href="#library">单词库</a> / 全库学习')+`<div class="page-heading"><div><span class="kicker">跨词书 · 去重后练习</span><h1>全库学习</h1><p>全部 ${Catalog.books.length} 本词书，共 ${DB.words.length.toLocaleString()} 个不重复词条。</p></div><a class="soft-link" href="#library">返回单词库 ↗</a></div><section class="panel all-study-panel"><h2>按自己的节奏，混合学一组。</h2><p>不区分词书与单元，从当前范围随机选词。每轮独立保存，可以随时退出再继续。</p><div class="all-study-controls"><label>词条类型<select id="allStudyType"><option value="all" ${allStudyType==='all'?'selected':''}>单词 + 词组</option><option value="word" ${allStudyType==='word'?'selected':''}>仅单词</option><option value="phrase" ${allStudyType==='phrase'?'selected':''}>仅词组</option></select></label><label>学习方式<select id="allStudyDirection"><option value="mixed" ${allStudyDirection==='mixed'?'selected':''}>选择 + 中文回忆</option><option value="en" ${allStudyDirection==='en'?'selected':''}>中文选英文</option><option value="zh" ${allStudyDirection==='zh'?'selected':''}>英文写中文</option></select></label><label>学习范围<select id="allStudyScope"><option value="unfinished" ${allStudyScope==='unfinished'?'selected':''}>尚未通过所选模式</option><option value="all" ${allStudyScope==='all'?'selected':''}>全部词条，可重复练习</option></select></label><label>每轮词数<select id="allStudyLimit">${[10,20,50,100].map(n=>`<option value="${n}" ${allStudyLimit===n?'selected':''}>${n} 个词</option>`).join('')}</select></label></div><div class="all-study-start"><span>当前范围 ${pool.length.toLocaleString()} 词 · 本轮最多 ${Math.min(pool.length,allStudyLimit)} 词</span><button class="primary" id="beginAllStudy" ${pool.length||selectedResume?'':'disabled'}>${selectedResume?'继续这轮学习':'开始全库学习'} →</button></div><p class="footer-note">相同单词只收录一条，两个方向分别练习，共享掌握度、错词和复习记录。拼写仍为单独的可选加练。</p></section>${resumes.length?`<section class="panel"><h3>继续未完成的全库学习</h3><div class="actions">${resumes.map(([key,s])=>`<button data-resume="${esc(key)}">${modeName(s.direction)} · 剩 ${s.queue.length} 项 →</button>`).join('')}</div></section>`:''}`;
 $('#allStudyType').onchange=e=>{allStudyType=e.target.value;renderAllStudy()};$('#allStudyDirection').onchange=e=>{allStudyDirection=e.target.value;renderAllStudy()};$('#allStudyScope').onchange=e=>{allStudyScope=e.target.value;renderAllStudy()};$('#allStudyLimit').onchange=e=>{allStudyLimit=Number(e.target.value);renderAllStudy()};$('#beginAllStudy').onclick=startAllStudy;bindResume();
}

